def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]

    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)

    out = [row[:] for row in grid]

    # Complete the outer rectangular frame.
    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            if r in (rmin, rmax) or c in (cmin, cmax):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # Extend interior horizontal strokes across the frame.
    for r in range(rmin + 1, rmax):
        if any(grid[r][c] != bg and grid[r][c + 1] != bg
               for c in range(cmin, cmax)):
            for c in range(cmin, cmax + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    return out
